import { section as s, table, figure } from './content-helpers.js';
const doc = (slug, category, title, description, summary, related, sections) => ({ collection: 'docs', slug, category, title, description, summary, related, sections });

export const productDocs = [
  doc('stock-compensation-report', 'Reporting', 'Prepare a stock compensation expense report',
    'Set valuation assumptions, select a fiscal period, and review Cap Table stock compensation expense, forfeiture reversals, and unrecognized cost.',
    'Review award values and expense recognition for a fiscal period.',
    ['stock-compensation-and-valuation', 'recording-valuations', 'rule-701-report', 'expense-attribution-straight-line-and-graded'], [
      s('prepare-inputs', 'Prepare the award and valuation records', `<p>Open <strong>Reports</strong> and select <strong>Stock comp expense</strong>. This report calculates expense for recorded options and RSUs. Check grant dates, quantities, vesting, cancellations, option strikes, and expirations first. Record the valuation covering each grant date under Settings.</p><p>The report supports review of US stock-based compensation under ASC 718 using the app’s valuation and attribution conventions. It does not determine whether every award is within that accounting model or prepare financial statements.</p>` + figure('stock-compensation-report.png', 1920, 1080, 'Stock compensation report showing the fictional Acme Robotics company and recorded valuation assumptions', 'The actual report with sample company records. Figures are illustrative.')),
      s('set-assumptions', 'Set the company’s reporting assumptions', `<p>Use <strong>Edit</strong> on the assumptions card. Enter expected volatility and the risk-free rate as percentages, such as <code>60</code> for 60%. Choose a fixed expected term in years or the simplified method, then choose straight-line or graded attribution and the fiscal year-end month.</p><p>Options require positive volatility to run the report. RSU-only records do not need option-pricing assumptions. The app uses Black-Scholes for options, with no dividends, and recorded grant-date share FMV for RSUs. Select assumptions appropriate to the awards with your accounting reviewer. The SEC’s <a href="https://www.sec.gov/rules-regulations/staff-guidance/staff-accounting-bulletins/staff-accounting-bulletin-no-110">SAB 110</a> explains conditions on using a simplified expected term; availability of the setting does not establish eligibility.</p>`),
      s('review-period', 'Review the period and exceptions', `<p>Select the fiscal year and either the full year or a quarter. Review grant-date fair value, expense in the selected period, cumulative expense, unrecognized cost, and the remaining recognition period.</p><p>A cancellation can produce a negative period expense when previously recognized cost for forfeited unvested units is reversed. Expiration of an earned, vested option is a different event.</p><p>Read every valuation note. Without grant-date FMV, the option calculation can use strike as a fallback; an RSU without FMV is unvalued. Without a usable option expiration, the model assumes a ten-year contractual term. Resolve these inputs before treating the output as a completed accounting schedule.</p>`),
      s('export-review', 'Export the report with its assumptions', `<p>Select <strong>Export CSV</strong>. Keep the exported assumptions and award notes with the numbers. Changing company assumptions later recalculates the report, so save the reviewed version and its supporting records.</p><p>For awards with performance conditions, liability treatment, modifications, or other terms beyond the model, determine the appropriate treatment outside this schedule. See <a href="/docs/calculation-methods-and-limits/">Calculation methods and limits</a> before reconciling to the ledger.</p>`),
    ]),
  doc('rule-701-report', 'Reporting', 'Review the Rule 701 report',
    'Inspect trailing compensatory sales, modeled Rule 701 ceilings, missing valuations, and disclosure flags in Cap Table.',
    'Review a US compensatory-securities report and its scope.',
    ['form-3921-report', 'recording-valuations', 'resolving-attention-items'], [
      s('understand-scope', 'Understand what the report checks', `<p>In <strong>Reports</strong>, select <strong>Rule 701</strong>. This is a US federal securities-law report. Rule 701 applies to eligible compensatory offerings by eligible issuers; passing a numerical check alone does not establish that an offering qualifies.</p><p>The SEC describes a sales limit based on the greatest of $1 million, 15% of total assets, or 15% of the outstanding class, with additional disclosure when sales exceed $10 million over twelve months. Read the <a href="https://www.sec.gov/resources-small-businesses/exempt-offerings/employee-benefit-plans-rule-701-0">SEC’s Rule 701 overview</a> and <a href="https://www.sec.gov/rules-regulations/staff-guidance/corporation-finance-interpretations/securities-act-rules">Rule 701 interpretations</a> for eligibility, valuation, timing, and disclosure requirements.</p>`),
      s('choose-window', 'Choose the window and asset assumption', `<p>Set <strong>Twelve months ending</strong> to the date under review. The report uses a rolling window rather than simply adding a calendar year. Set the fiscal year end and the applicable year-end total assets in reporting assumptions if you want the asset-based ceiling included.</p><p>With total assets unset, the app skips that ceiling. Its currency warning matters: statutory thresholds are in US dollars, and the app does not convert a company’s non-USD records into dollars for this comparison.</p>`),
      s('reconcile-sales', 'Reconcile the records counted as sales', `<p>The app counts option grants at strike, RSUs at the recorded FMV on the grant date, and shares sold to employee and advisor holders at issue price. It excludes founder stock and investor rounds from compensatory sales. Check stakeholder classifications as well as securities.</p><p>An RSU without a valuation covering its grant date is counted at zero in the displayed sales price and flagged. That can understate the total. Review the rows, share counts, valuation basis, and historical windows flagged by the report before interpreting the summary.</p>`),
      s('use-output', 'Use the output for review', `<p>Export the selected report to CSV, including its assumptions and window history. Review classification, aggregation, issuer eligibility, and disclosure delivery with the person responsible for the offering. The app does not deliver disclosures or file an exemption notice.</p><p>A change to an old grant or valuation can change previous rolling totals. Recheck the affected windows after correcting records and retain the reviewed export.</p>`),
    ]),
  doc('form-3921-report', 'Reporting', 'Prepare Form 3921 supporting data',
    'Review recorded ISO exercise certificates, identify missing fair market values, and export supporting Form 3921 data from Cap Table.',
    'Prepare exercise records for a US information-return workflow.',
    ['exercising-options', 'iso-and-nso-options', 'recording-valuations'], [
      s('scope', 'Start with the US reporting requirement', `<p>Select <strong>Reports</strong>, then <strong>Form 3921</strong>. The report organizes recorded ISO exercises for a selected calendar year. Form 3921 concerns stock transferred on exercise of qualifying incentive stock options, subject to the IRS instructions and exceptions. It is separate from Form 3922 for certain employee stock purchase plan transfers.</p><p>Use the current <a href="https://www.irs.gov/instructions/i3921">IRS instructions for Forms 3921 and 3922</a> to determine filing and recipient-statement obligations. The app produces supporting data, not an electronically submitted return.</p>`),
      s('prepare-exercises', 'Check the grant and certificate', `<p>Confirm that each applicable grant is recorded as an ISO and that each exercise has a linked certificate with its actual exercise date. The certificate provides the dated event and exercise price. The report uses the recorded valuation covering that exercise date for FMV.</p><p>The <strong>Exercises with no certificate</strong> section identifies exercised quantities that cannot yet be assigned to a dated certificate. Use <strong>Issue certificate</strong> after checking the original exercise records. Do not record the same exercise again to make it appear in the report.</p>`),
      s('review-boxes', 'Review the mapped values', table('Form 3921 data in the app', ['Field', 'Record to check'], [
        ['Grant date', 'Original option grant date'], ['Exercise date', 'Linked exercise certificate date'],
        ['Exercise price', 'Price paid per share on the certificate'], ['FMV at exercise', 'Valuation covering the exercise date'],
        ['Shares transferred', 'Quantity on the exercise certificate'],
      ]) + `<p>Resolve missing FMV warnings before completing the filing data. Names, taxpayer identification numbers, addresses, and any additional corporation details must be reconciled with the filer’s records. The cap table is not a complete taxpayer-information system.</p>`),
      s('export', 'Export and complete the filing separately', `<p>Choose the year and select <strong>Export CSV</strong>. The report displays calendar reminders, but verify the applicable year’s furnishing and filing dates, electronic-filing requirements, exceptions, and any relief through the IRS. A CSV download does not furnish a recipient statement or file a return.</p><p>Retain the final filed version and delivery evidence separately from the working cap table. If exercise records change, determine whether the filing needs a correction.</p>`),
    ]),
  doc('planning-hiring-grants', 'Plan and review', 'Plan hiring grants and pool capacity',
    'Build a hiring forecast in Cap Table, size grants by shares or percentage, review plan shortfalls, and prepare actual option grants.',
    'Connect proposed hiring to equity-plan capacity and round assumptions.',
    ['option-pool-hiring-forecast', 'managing-equity-plans', 'modeling-a-funding-round'], [
      s('add-role', 'Add a planned role', `<p>Open <strong>Share classes</strong>, find <strong>Hiring plan</strong>, and choose <strong>Add role</strong>. Enter a role, whole-number headcount, and start month. Set a grant size per hire as a share count or percentage. Percentage sizing uses the current fully diluted share count, so its share equivalent can change as the cap table changes.</p><p>Choose the destination plan when several eligible plans are available. A row using the default plan follows the most recently adopted open plan that accepts options. Choose an explicit destination when the forecast depends on a particular reserve.</p>` + figure('hiring-plan.png', 1113, 368, 'Hiring plan with four software engineers at 40,000 shares per hire and a remaining-pool forecast', 'A sample hiring row entered in the app. Planned grants do not change current ownership.')),
      s('read-forecast', 'Review timing and shortfalls', `<p>The forecast draws down the available pool by planned grant month and identifies a shortfall. Also inspect shortfalls by plan: aggregate capacity does not mean that the plan intended for an award has enough room.</p><p>An unscheduled role cannot establish the month a grant will occur. Review rows outside the forecast horizon as well as those plotted. The forecast describes proposed awards and does not reserve shares, issue securities, or change current ownership.</p>`),
      s('connect-round', 'Use the forecast in round planning', `<p>When the forecast is short of shares, the card offers <strong>Cover the shortfall in the round model</strong>. It opens Round modeling, where <strong>Set the target to cover the plan</strong> solves the post-round pool target that covers the planned grants and fills the field with it. Enter the pre-money valuation and investment first: the button says what is missing rather than guessing, and it reports when the round cannot carry a top-up that large. Review the resulting dilution and destination plan afterwards. The target depends on the recorded hiring assumptions, and it does not establish that a reserve increase has been adopted.</p><p>Use the pencil action on a role to change its headcount, start month, grant sizing, or available plan choice. Use its delete action to remove a proposed role and review the resulting forecast. Changing or deleting a planned role does not alter an award already issued from it. Compare a base hiring case with a delayed or expanded case by editing the forecast deliberately and retaining the assumptions you reviewed. See <a href="/guides/option-pool-hiring-forecast/">Build an option-pool hiring forecast</a> for a worked share-count example.</p>`),
      s('issue-grant', 'Move from planning to an actual award', `<p>The planned row’s grant action opens an option form prefilled with the per-hire share quantity and plan. Select the actual holder and confirm grant date, strike, vesting, classification, and approvals before saving.</p><p><strong>The planned row remains after issuance.</strong> Reduce its headcount or remove it when the planned hires are complete. Otherwise, the issued award reduces actual availability while the unchanged row still forecasts a future grant.</p>`),
    ]),
  doc('recording-valuations', 'Reporting', 'Record and maintain 409A valuations',
    'Record provider-supplied share fair market values in Cap Table and review their effect on option strikes, reports, and valuation reminders.',
    'Maintain valuation dates, prices, and supporting reports.',
    ['stock-compensation-report', 'form-3921-report', 'early-exercise-and-83b', '409a-valuations-explained'], [
      s('record-value', 'Record the provider’s value', `<p>In <strong>Settings</strong>, use the 409A valuation section to record a value. Enter the effective date, positive fair market value per share, and an optional note identifying the provider or valuation event. Save the record, then attach the supporting report from its valuation entry in Settings.</p><p>Cap Table records a valuation supplied by you. It does not perform a 409A valuation, select the appropriate methodology, or establish that a value satisfies US tax requirements.</p>`),
      s('check-dates', 'Check dates and split units', `<p>Use the valuation’s effective date, which may differ from the date you enter it. Reports select the recorded valuation in force on the relevant grant or exercise date.</p><p>If backfilling a valuation dated before a recorded stock split, follow the form’s unit warning: enter the price in today’s post-split units and compare the displayed historical equivalent with the provider’s report. For example, $2 per share before a 2-for-1 split corresponds to $1 in current units.</p>`),
      s('review-uses', 'Review where the value is used', `<p>Recorded FMV helps prefill option strikes, flag below-FMV strikes, value RSUs and options in expense reports, and supply exercise-date values for Form 3921 supporting data. Correcting valuation history can therefore change several reports.</p><p>The app also flags an old valuation or one overtaken by a priced round. A reminder is a review prompt, not a professional determination that the value is valid or invalid for every purpose.</p>`),
      s('correct-history', 'Correct history with the source report available', `<p>Review the history entry and its attachments before deleting or replacing an incorrect valuation. Re-run affected reports after the correction and retain the version used for a completed review or filing. A company can keep up to 40 recorded valuations. Deleting a valuation has no Undo action; review any file-deletion choice and retain the source report before correcting the history.</p><p>Do not substitute a financing’s preferred-share price for common-share FMV without a supporting basis. Read <a href="/guides/stock-compensation-and-valuation/">Stock compensation and valuation assumptions</a> for the distinction between a share value, option value, and expense.</p>`),
    ]),
  doc('exercising-options', 'Ownership changes', 'Exercise options and issue certificates',
    'Record option exercises, issue missing exercise certificates, review early exercise, and cancel remaining options in Cap Table.',
    'Keep option quantities and resulting share certificates connected.',
    ['option-grant-lifecycle-example', 'early-exercise-and-83b', 'form-3921-report', 'post-termination-exercise-windows'], [
      s('open-actions', 'Open the grant’s lifecycle actions', `<p>In <strong>Securities</strong>, find the option grant and open its lifecycle actions. Review vested and unexercised quantities, expiration, any departure deadline, and whether early exercise is allowed. Choose <strong>Record exercise</strong>.</p><p>Enter a whole-number quantity and the actual exercise date. The app checks the award’s available quantity and what could be exercised on that date. Use the underlying exercise notice and payment records to reconcile the result.</p>` + figure('option-exercise.png', 480, 634, 'Option exercise dialog with quantity, date, certificate choice, and share class for sample grant OPT-1', 'The actual exercise form for a sample option grant. Review the terms and date before recording a real exercise.')),
      s('issue-certificate', 'Review the certificate and cost', `<p>The exercise form can also issue the share certificate. Review the selected class and the exercise cost, calculated from quantity and strike. If there are no share classes, the workflow can create Common Stock; review its authorization afterward.</p><p>Keeping <strong>Also issue the share certificate</strong> selected records the exercise and linked certificate together. If you record the exercise without a certificate, those quantities remain represented on the grant side of the fully diluted count until a certificate represents them.</p><p>For example, exercising 5,000 options at $1.20 records $6,000 of exercise consideration. It creates 5,000 shares when the certificate is issued; the app does not collect the money.</p>`),
      s('spread', 'Review the spread before recording the exercise', `<p>As you enter a quantity and date, the exercise form states the exercise cost at the grant’s strike and, separately, the bargain spread: the fair market value in force on that date from the recorded 409A, the spread per share multiplied by the quantity, and what that element is for this grant type. On an ISO the spread is described as an alternative-minimum-tax preference item at exercise rather than ordinary income; on an NSO it is described as ordinary income subject to withholding.</p><p>For an ISO, the form also names the date a qualifying disposition becomes possible: two years from the grant and one year from the exercise, whichever is later. An exercise of 5,000 ISOs granted January 1, 2025 and exercised March 1, 2026 qualifies from March 1, 2027.</p><p>If the strike is at or above the fair market value on the date, the form says there is no bargain element. If no valuation covers the date, it says the spread cannot be estimated and points to Settings to record the value your provider gave you. These lines are arithmetic from the records on file: no rates, brackets, or withholding are applied, and nothing here is a tax position. The same figures appear on the holder’s statement beside the resulting certificate.</p>`),
      s('certify-later', 'Issue a missing certificate without another exercise', `<p>Choose <strong>Issue exercise certificate</strong> for quantities already recorded as exercised. Enter the quantity covered, original exercise date, and class. This supplies the linked certificate without increasing the exercised counter again.</p><p>Check that the remaining uncertified quantity decreases and that the certificate appears under the intended holder. Form 3921 uses dated ISO exercise certificates, so an exercise entered only as a grant counter is insufficient for that report.</p>`),
      s('early-and-cancelled', 'Review early exercise and cancellation separately', `<p>An early exercise can include unvested options when the grant allows it. The resulting certificate carries reverse vesting. Review its schedule and the applicable 83(b) records; recording the exercise does not file an election.</p><p><strong>Cancel grant</strong> records cancelled units and a cancellation date. Review the proposed quantity and recycling destination. Unvested forfeiture and cancellation of expired, vested options have different effects on expense and ownership. Use the expiry or departure workflow when that is the actual event. Retain the original grant and review History after saving.</p>`),
    ]),
  doc('settling-and-cancelling-rsus', 'Ownership changes', 'Settle and cancel RSU awards',
    'Record vested RSU settlements into shares, review liquidity conditions, and record award cancellations with the correct date and plan treatment.',
    'Reconcile RSUs, settlement certificates, and cancelled units.',
    ['exercising-options', 'options-rsus-and-restricted-stock', 'recording-a-departure'], [
      s('review-award', 'Review the award before settlement', `<p>Open the RSU’s lifecycle actions in <strong>Securities</strong>. Check vested and unsettled units, the holder, share class, plan, and recorded liquidity condition. A time-vested award may still have an additional settlement condition in its agreement.</p><p>The app records the event you enter. It does not verify that a liquidity event occurred, authorize settlement, or calculate payroll withholding.</p>`),
      s('settle', 'Record a settlement into shares', `<p>Choose <strong>Record settlement</strong>, enter the whole-number units and actual settlement date, and review the receiving share class. The app limits settlement to units vested and unsettled on that date.</p><p>Settlement issues a linked share certificate. Unlike an option exercise, there is no strike-price purchase step and no separate option to leave the settlement uncertificated. After saving, check both the award and certificate.</p><p>For example, settling 3,000 units of a 10,000-unit award leaves 7,000 units before considering cancellations or other settlements. The certificate represents the 3,000 issued shares.</p>`),
      s('cancel', 'Record cancelled units', `<p>Choose <strong>Cancel units</strong> and check the date and proposed amount against the event. The form accounts for units already settled and the vesting schedule. Review where cancelled units go under the plan’s recycling rules.</p><p>A departure review may identify RSUs requiring cancellation, but the award cancellation is a separate action. Do not reduce the original grant quantity to approximate a forfeiture.</p>`),
      s('reconcile', 'Reconcile the award after the event', `<p>Compare original quantity, settlements, cancellations, and remaining units. Review the holder’s statement, plan availability, fully diluted ownership, and the stock compensation report where relevant.</p><p>Cash settlement, tax withholding, and net-share settlement arrangements require separate reconciliation if the actual transaction includes them. The standard workflow described here records a gross settlement into linked shares.</p>`),
    ]),
  doc('configuring-share-classes', 'Maintain your records', 'Configure common and preferred share classes',
    'Set share-class authorization, issue prices, preferences, seniority, participation, and anti-dilution terms in Cap Table.',
    'Record the class terms used by ownership and financing models.',
    ['anti-dilution-protection', 'liquidation-preferences-explained', 'closing-a-funding-round', 'common-and-preferred-stock', 'recording-preferred-dividends'], [
      s('create-class', 'Create the class from the governing records', `<p>Open <strong>Share classes</strong> and add a class. Enter its name, choose common or preferred, and record authorized shares and original issue price. Use the actual class name so certificates and imports can be reconciled consistently.</p><p>Authorization is the class limit; creating a class does not issue that many shares. Issuances are separate security records. An equity plan’s reserve is also a separate record.</p><p>The app checks issued shares against the authorized count wherever the count can be passed. Typing an authorized number below what the class has already issued warns at the field, a certificate or a round close that would take the class past its count warns before it writes, the CSV preview names a class a file would take over, and the split preview names a class its rounding alone would take over. A class already over its count is listed under <strong>Needs attention</strong> and marked <em>over authorized</em> on the Share classes table. Raising the count is a charter amendment, so record the amendment and then raise the number.</p><p>The Share classes table counts every recorded security, including records dated after today, and says so beneath the table when any exist. The dashboard and the cap table count those records from their own dates instead, which is why the two views can differ while a future-dated grant is on file.</p>`),
      s('preferred-terms', 'Set preferred payment rights', `<p>For preferred stock, enter the liquidation-preference multiple and seniority. Higher seniority is paid first in the exit model; equal-ranked claims share proportionally when a tier has insufficient proceeds. Enable participating preferred only when that matches the class.</p><p>The controls express the app’s supported terms. They do not represent every possible charter provision. A participation cap or a dividend schedule is a separate, dated record: see the next section.</p>`),
      s('caps-and-dividends', 'Record participation caps and dividend terms', `<p>Open <strong>Participation cap and dividends</strong> on a preferred class and append an amendment with its effective date and the charter or amendment it comes from. A cap is a multiple of invested capital, per holder, and the amendment states whether the initial preference and accrued dividends count toward it. Only a participating class can carry a cap.</p><p>Dividend terms record the annual rate, the accrual window, whether the dividend is cumulative, simple or compound accrual on actual days over 365, and what happens to unpaid dividends on conversion and at liquidation. Non-cumulative dividends accrue nothing on their own; record declarations and payments on the certificate. Amendments are permanent and dated: a later amendment changes results from its date on and leaves earlier accrual as it was. Each certificate in the class keeps the money it was issued for as its dividend basis through splits and transfers. Read <a href="/guides/liquidation-preferences-explained/">Liquidation preferences explained</a> for how a cap changes the exit model, and keep the signed terms attached.</p>`),
      s('anti-dilution', 'Set the anti-dilution method', `<p>Select none, broad-based weighted average, or full ratchet. The round model uses the selected method when a lower-priced financing triggers an adjustment. If a recorded down round already lowered the conversion price, the form identifies that adjusted price separately from the original issue price.</p><p>Review <a href="/guides/anti-dilution-protection/">Anti-dilution protection explained</a> and compare the capitalization definition and exclusions in the agreement with the model. Selecting a label does not implement bespoke contractual exceptions.</p>`),
      s('review-changes', 'Review changes against existing securities', `<p>After saving, inspect the issued certificates assigned to the class, the funding model, and an exit scenario. Class terms can affect all of those results. A class referenced by existing records can be protected from deletion, including closed certificate history. Read the specific dependency message; a zero current outstanding balance is not proof that the class has no records.</p><p>Use the stock-split workflow for a proportional restatement of share quantities and per-share terms. Editing the class price alone would not carry out a split across the company’s records.</p>`),
    ]),
  doc('advanced-vesting', 'Maintain your records', 'Configure vesting schedules and acceleration',
    'Enter monthly, quarterly, annual, or custom vesting schedules and record acceleration terms for equity awards in Cap Table.',
    'Translate dated vesting terms into a verifiable schedule.',
    ['vesting-acceleration', 'vesting-and-option-pools', 'recording-shares-and-grants'], [
      s('time-schedule', 'Choose the schedule and start date', `<p>Open the security form and review the vesting fields for the selected instrument. For a time-based schedule, choose monthly, quarterly, or annual cadence and enter the duration in months and cliff. Options, RSUs, and restricted shares offer a separate <strong>Vesting start</strong> field. It defaults to the grant or issue date until you enter a different date.</p><p>The vesting start can precede the grant date to credit prior service, or follow it for a later start. The grant date remains the award’s effective date and the date used for grant-date valuation; an award cannot be exercised or settled before it exists. CSV imports and JSON backups preserve the independent start. Custom tranches use their own explicit dates. The expense report continues to assume accounting service inception at the grant date and flags awards whose vesting start differs; a separate accounting service period is not modeled. Check the first vesting date and full-vest date after saving, especially when the start date falls near the end of a month.</p>`),
      s('custom-tranches', 'Enter a custom dated schedule', `<p>Choose <strong>Custom tranches</strong> when the schedule cannot be represented by the regular cadence. Add each vesting date and its share quantity. The rows must cover the applicable schedule quantity; review the total shown by the editor. A schedule can contain up to 600 tranches.</p><p>For a 12,000-unit grant, a simple custom example is 3,000 units on the first agreed date and 9,000 on the second. Do not enter a percentage in a field asking for shares. Custom dates represent recorded vesting steps, not an engine that verifies performance milestones.</p>`),
      s('acceleration', 'Record acceleration terms', `<p>Choose the acceleration trigger and the percentage of the unvested balance that accelerates. Single-trigger and double-trigger terms are distinct. Use the agreement’s percentage and conditions, and keep the agreement attached.</p><p>These terms are used by the exit scenario’s change-of-control assumption. Ordinary time-based vesting does not automatically accelerate merely because a scenario is saved. Read <a href="/guides/vesting-acceleration/">Vesting acceleration explained</a> before comparing exit cases.</p>`),
      s('check-existing-events', 'Respect exercises and settlements already recorded', `<p>When correcting a schedule, review earlier exercises, settlements, and cancellations. The app can refuse a schedule that would put an already recorded exercise ahead of available vesting. Correct the inaccurate record rather than erasing a valid transaction.</p><p>Review the holder’s vesting display, upcoming calendar, plan balance, and affected reports after saving. Use History to distinguish the effective dates from the date the correction was entered.</p>`),
    ]),
  doc('recording-convertible-instruments', 'Maintain your records', 'Record SAFEs and convertible notes',
    'Enter SAFE and note balances, caps, discounts, interest, maturity, and conversion records in Cap Table.',
    'Maintain the actual terms behind convertible financing models.',
    ['safes-and-convertible-notes', 'convertible-note-interest-example', 'closing-a-funding-round', 'pro-rata-rights-explained', 'mfn-clauses-explained'], [
      s('enter-agreement', 'Choose the instrument and holder', `<p>Use <strong>Issue security</strong> and select <strong>SAFE</strong> or <strong>Note</strong>. Choose the actual investor, enter the agreement date and principal, and attach the signed instrument after saving. A principal is a monetary balance, not a number of shares.</p><p>Use separate records for separate instruments when they have distinct terms or dates. The current ownership table lists outstanding convertibles separately until they become shares.</p>`),
      s('set-conversion', 'Set the cap and discount', `<p>Enter the valuation cap, or leave it blank for an uncapped instrument. Enter discount as a whole percentage, such as <code>20</code> for a 20% discount. For a SAFE, select the actual pre-money or post-money cap type.</p><p>The round model compares the applicable cap and discount conversion prices. Side letters are separate records: a pro-rata right or a most-favored-nation clause is entered under its own heading on the security (see below). A custom financing definition the app does not offer stays in the agreement, and the model should be reconciled against it before closing.</p>`),
      s('rights-and-mfn', 'Record pro-rata rights and MFN clauses', `<p>Open <strong>Pro-rata participation rights</strong> on any security and add a right with its agreement reference, eligibility window and the financings it applies to. Choose the ownership basis the agreement actually uses: a fixed percentage, the holder’s pre-round fully diluted ownership, the YC post-money SAFE side letter, or the original YC right that applies to the financing after the SAFE converts. These are different denominators and are not interchangeable.</p><p>On a SAFE or note, <strong>Most-favored-nation terms</strong> records the clause: which terms it covers, its eligibility window and which later instruments it can look at. Once a later instrument qualifies, record an explicit election with its date and evidence. The election copies that instrument’s terms as they stood and keeps the original terms beside it; nothing on the instrument is overwritten, and a round scenario applies the election only when it selects it. Rights, clauses and elections are permanent records, appended rather than edited. Promised options, bespoke denominator exclusions and MFN terms outside the cap, discount and SAFE convention are not modeled and cannot be entered.</p>`),
      s('note-interest', 'Record note interest and maturity', `<p>For a note, enter the annual simple-interest percentage and maturity date. Compare the resulting balance at the intended modeling date with the note calculation in your records. The app uses simple interest, so a compounding instrument needs separate review.</p><p>When a note is overdue, use its <strong>Needs attention</strong> action to record an agreed extension or that the maturity date was dealt with. Marking maturity as resolved does not itself remove the outstanding instrument, stop all modeled consequences, repay cash, or convert the note.</p>`),
      s('record-conversion', 'Review the linked conversion', `<p>Use a funding-round model to inspect conversion shares, then the close workflow to apply the reviewed financing. The resulting certificate is linked to its source instrument, and the source is marked converted.</p><p>After conversion, terms that determined the certificate’s size are constrained by that relationship. Review the whole transaction if the records need correction. Creating an unrelated share certificate and leaving the SAFE active would not represent a completed conversion.</p>`),
    ]),
  doc('managing-warrants', 'Maintain your records', 'Record and review warrants',
    'Record warrant quantities, strike prices, and expiration dates and understand their treatment in Cap Table ownership and exit models.',
    'Track warrant exercises, cancellations, and expiration.',
    ['recording-shares-and-grants', 'recording-convertible-instruments', 'calculation-methods-and-limits', 'exit-waterfall-step-by-step'], [
      s('record', 'Record the warrant terms', `<p>Choose <strong>Warrant</strong> in the security form. Enter the holder, quantity, strike price, issuance date, and expiration where applicable. Review the supporting agreement and attach it to the record.</p><p>A warrant is a distinct instrument. Do not use an employee option merely to make a different lifecycle menu available, because employee-option classification and plan treatment would misdescribe the record.</p>`),
      s('ownership', 'Review ownership and plan treatment', `<p>Warrants contribute to the app’s fully diluted count, while an unexercised warrant is not an issued share certificate. Warrants do not draw from equity-plan reserves.</p><p>The exit model accounts for warrant strike prices when calculating economic participation. A warrant’s fully diluted quantity alone is not a promise of cash proceeds at every sale value.</p>`),
      s('expiry', 'Record exercises and cancellations', `<p>Use <strong>Lifecycle actions</strong> on the warrant to record a cash exercise or dated cancellation. An exercise issues a linked share certificate at the warrant’s strike price and reduces the remaining rights in one save. Deleting that certificate undoes the exercise; the original warrant remains available for historical reporting.</p><p>Unexercised rights stop contributing to fully diluted ownership and exit proceeds after the expiration date. They remain included in snapshots on or before that date. An expired warrant remains available for review, recording an earlier exercise, or correcting its terms after a documented extension.</p>`),
      s('limits', 'Recognize unsupported warrant events', `<p>Cashless exercise and bespoke conversion ratios are not modeled. Reconcile those events separately. Warrants do not use employee vesting schedules or draw from equity-plan reserves.</p>`),
    ]),
  doc('resolving-attention-items', 'Review and recovery', 'Resolve Needs attention items',
    'Understand Cap Table alerts for expired awards, mature notes, valuation history, departed holders, equity plans, and 83(b) records.',
    'Follow each reminder to the record or action that resolves it.',
    ['troubleshooting-and-recovery', 'recording-a-departure', 'recording-valuations'], [
      s('review-list', 'Read the item before acting', `<p>Open <strong>Needs attention</strong> to review records whose dates or status call for action. Check the named holder, security, quantity, and date. An alert identifies a condition in the recorded data; it does not independently verify an agreement or establish that an obligation was fulfilled.</p><p>The Home dashboard shows a shorter attention list. Open the full page to review all items before a financing or report export.</p>`),
      s('actions', 'Use the action for the actual event', table('Attention items and their follow-up', ['Item', 'What to review'], [
        ['Expired options', 'Cancel remaining lapsed options on the applicable date; review the plan destination. The item names which clock ran out: the grant reaching the end of its term, or a holder’s post-termination window closing. Multiple expired grants can be reviewed for bulk cancellation.'],
        ['Departed holder’s awards', 'Review cancellation of unvested options or RSUs against the departure and prior events.'],
        ['Expired warrant', 'Open the warrant record to review its exercises and cancellations, and inspect the agreement and any extension.'],
        ['Matured note', 'Record that maturity was dealt with or enter an agreed new maturity date.'],
        ['83(b) record', 'Record the actual filing date or that the election was not filed. The item appears once the 30-day window has closed with nothing recorded; the window itself is listed under upcoming events while it is open.'],
        ['Valuation reminder', 'Record the provider’s new valuation after reviewing the relevant date. The reminder is raised by a valuation twelve months old or more, or by a priced round closing after it was set.'],
        ['Expired plan', 'Review retirement or an actual extension of the plan’s expiration. Its unallocated shares still count as fully diluted until it is retired.'],
        ['Class over its authorized shares', 'A class holds more issued shares than its authorized count. Raise the authorized shares under Share classes once the charter amendment is signed, rather than editing certificates to fit.'],
      ])),
      s('what-resolution-means', 'Understand what clearing an item means', `<p>Recording a note’s maturity as dealt with does not repay cash or remove the note from convertible models. Recording an 83(b) status does not file an election or make a late election timely. Changing an expiration should reflect a real amendment.</p><p>For a bulk cancellation, inspect the records and confirmation first. The operation takes a restore point and records the cancellations; it is not simply dismissing notifications.</p>`),
      s('verify', 'Check the resulting records', `<p>After the action, inspect the security, plan balance, and History. Re-run any ownership view or report affected by the event. If an alert remains, check the condition it describes rather than repeating a transaction.</p><p>A clean attention list does not certify complete records or regulatory compliance. Some unsupported terms and missing source documents cannot be detected from the data alone.</p>`),
    ]),
  doc('troubleshooting-and-recovery', 'Review and recovery', 'Troubleshoot saves, imports, and recovery',
    'Resolve Cap Table save conflicts, interrupted operations, rejected edits, import problems, and company-backup restoration.',
    'Recover working records and understand why an action was refused.',
    ['exports-and-history', 'csv-field-reference', 'workspace-and-documents', 'resolving-financing-refusals'], [
      s('save-errors', 'Distinguish a connection problem from a refused change', `<p>Read the complete save message. A connection failure calls for checking connectivity and retrying through the displayed action. A refused edit can instead mean that a date, quantity, related record, or application limit prevents the change.</p><p>If another tab or device changed the company, preserve any unsaved input you need, reload the latest records, and reassess the proposed edit. Repeating the same stale form is not a way to merge concurrent changes.</p>`),
      s('interrupted-operation', 'Follow recovery prompts after an interrupted operation', `<p>If the app reports an unfinished change, follow its recovery and retry controls before entering new transactions. The app keeps recovery information for interrupted writes. Do not manually delete cloud keys to dismiss the message.</p><p>After recovery, inspect the intended result and History before recording the event again. If the operation completed, repeating an import, issuance, or exercise could duplicate it.</p>`),
      s('unreadable-record', 'Recover when a record cannot be read at startup', `<p>If a stored record comes back unreadable, or was written by a newer version, Cap Table stops before loading the company rather than starting on an empty cap table and saving over the record. The screen that reports this offers the ways back that do not depend on the damaged record: restore one of the company’s own snapshots, restore from a downloaded JSON backup, or open another company under the account. Nothing is written until you confirm one of them, and the company then loads again through the ordinary startup.</p><p>Try again first, since a transient read failure clears on reload. If the list of companies itself cannot be read, only the retry is offered; the companies’ records remain in your Puter cloud.</p>`),
      s('import-backup', 'Restore a company from a JSON backup', `<p>In Settings, choose the backup import action and select a company JSON export. Review whether to <strong>Replace this company</strong> or import into <strong>A new company</strong>. Replacing changes the selected company’s working records; a new-company import creates and switches to another company.</p><p>If creation succeeds but importing fails, the dialog identifies the new empty company and allows retrying into that same destination. Check the company selector before starting another import. JSON backup import is different from the additive CSV importer.</p><p>Settings also lists restore points. Review the timestamp and label before restoring. Up to five points are kept, and size constraints can retain fewer; use downloaded backups for versions you need to keep independently.</p>`),
      s('common-refusals', 'Resolve common validation problems', `<ul><li><strong>Award exceeds plan capacity:</strong> check its destination, effective date, existing commitments, and the actual adopted reserve.</li><li><strong>Exercise or settlement exceeds vesting:</strong> check the event date, schedule, prior claims, and early-exercise permission where applicable.</li><li><strong>Linked certificate cannot be edited:</strong> inspect its transfer, exercise, or conversion chain before correcting the underlying transaction.</li><li><strong>Import duplicates:</strong> securities are not automatically deduplicated. Inspect the preview before repeating the import.</li><li><strong>Missing attachment:</strong> check the Puter account and whether the backing file remains accessible. A JSON backup is not an archive of file contents.</li></ul><p>When escalating a persistent issue, note the app action, exact message, company context, and whether it followed a restore or concurrent edit. Use a minimal reproduction without exposing private agreements or holder information.</p>`),
    ]),
  doc('workspace-and-documents', 'Start here', 'Manage companies, account access, and documents',
    'Switch company workspaces, update profiles and appearance, attach supporting documents, and understand storage and deletion in Cap Table.',
    'Keep company records and supporting files in the right workspace.',
    ['dashboard-and-search', 'troubleshooting-and-recovery', 'exports-and-history'], [
      s('companies', 'Create and switch company workspaces', `<p>Use the company selector to open the company list, create a company, or switch to an existing one. Review the selected company before importing data, issuing a security, changing assumptions, or exporting a report. Settings lets you update its profile and currency.</p><p>A currency setting labels and formats the company’s monetary amounts. It does not convert existing values using exchange rates. Keep records in a consistent currency and reconcile any multi-currency transaction separately.</p>`),
      s('account', 'Understand account access and appearance', `<p>The app uses your Puter account for sign-in and cloud records. When running inside Puter, it uses that environment’s account context. On the standalone website, use the sign-in flow; sign-out is available where the app offers it.</p><p>A stakeholder email is contact information, not an invitation granting access. Downloading a statement does not share a live workspace. Use Settings to choose light, dark, or system appearance. Mobile navigation groups additional views under More.</p>`),
      s('attachments', 'Attach the supporting document to its record', `<p>Save a security before adding supporting files to its attachment section. Valuation history entries also offer attachments. Choose <strong>Attach file</strong>, select a PDF or image, and wait for the upload to finish. Attachment uploads and removals save immediately, independently of the security form’s Save changes button. Each attachment can be up to 25 MiB. Open the uploaded filename to confirm it is the intended document.</p><p>Files are stored separately in Puter. Removing an attachment removes the reference and can delete its backing file unless another company or restore point still references it. Read the confirmation. Retain documents separately when making a portable company backup. See <a href="/docs/managing-attachments/">Attach, open, and retain documents</a> for immediate saves, pop-up handling, and file cleanup.</p>`),
      s('deletion', 'Distinguish sign-out, reset, and deletion', `<p>Signing out does not delete company records. Starting fresh from sample data, wiping a company’s working data, and deleting a company are different operations with different confirmations. Export anything you need before using a reset or deletion action.</p><p>History is preserved through working-data imports, wipes, undo, and restores within a company. That does not mean deleting the company is a harmless way to archive it. Review the company identity and the stated effect before confirming.</p>`),
    ]),
  doc('csv-field-reference', 'Reference', 'CSV import field reference',
    'Look up supported Cap Table CSV columns, required values, instrument-specific fields, formatting, and import limitations.',
    'Match spreadsheet columns to the importer’s supported fields.',
    ['importing-a-cap-table', 'calculation-methods-and-limits', 'advanced-vesting', 'recording-preferred-dividends'], [
      s('format', 'Use the templates and review column mapping', `<p>Download the stakeholder or securities template from <strong>Settings → Import from CSV</strong>. The importer recognizes comma, semicolon, and tab separators from the header, and supports quoted fields containing separators or newlines. Verify the preview rather than relying solely on automatic matching.</p><p>Use explicit ISO dates such as <code>2026-09-09</code>, whole share counts, and separate monetary and quantity columns. Percentage fields use percentage values, such as <code>20</code> for 20%. Amounts use the selected company’s currency.</p>`),
      s('stakeholders', 'Stakeholder columns', table('Stakeholder CSV fields', ['Column', 'Use'], [
        ['Name', 'Required. Holder name used to match securities.'], ['Email', 'Optional valid email address.'],
        ['Type', 'Holder category, such as founder, investor, employee, advisor, or entity. Review the mapped result.'],
      ]) + `<p>Import stakeholders before securities. Existing names and duplicate names can be skipped; check the preview’s reasons. If distinct entities have the same name, resolve the identity and naming in the source before relying on name-based matching.</p>`),
      s('securities', 'Security columns', table('Security CSV fields', ['Column', 'Use'], [
        ['Stakeholder; Security type; Date', 'Required. Match the holder; identify shares, options, RSUs, warrants, SAFEs, or notes; supply the event date.'],
        ['Share class; Quantity', 'Class name where applicable and the share or award quantity.'],
        ['Price per share; Strike price', 'Share issue price or option/warrant strike, as applicable.'],
        ['Principal; Valuation cap', 'Convertible principal and optional cap. These are monetary amounts.'],
        ['Discount (%); Interest (%)', 'Conversion discount and note simple-interest rate.'],
        ['SAFE cap type', 'Pre-money or post-money SAFE basis.'],
        ['Vesting (months); Cliff (months); Vesting start', 'Regular vesting terms where applicable.'],
        ['Expires; Maturity date', 'Expiration for relevant instruments; note maturity.'],
        ['83(b) filed', 'Actual election filing date for relevant restricted stock.'],
        ['Plan', 'Equity-plan name for options/RSUs; use none for an award outside all plans.'],
        ['Pro-rata rights JSON; MFN JSON', 'Optional structured negotiated terms. See the section below.'],
        ['Dividend events JSON; Economic basis JSON', 'Optional dividend declarations and payments, and the original investment they accrue on, for a share certificate.'],
      ]) + `<p>A blank Plan can resolve when exactly one plan is eligible; otherwise identify it explicitly. The preview can propose missing classes. Confirm their names and review their full terms after import.</p>`),
      s('financing-terms', 'Import and export negotiated financing terms', `<p>Four optional columns carry structured terms as JSON, in the shape the <strong>Export financing terms</strong> report writes from the Securities view. That report is the practical way to produce them: it lists every class with dated preferred terms and every security carrying rights, an MFN clause, dividend events, an economic basis, or financing evidence.</p><ul><li><strong>Pro-rata rights JSON</strong> and <strong>MFN JSON</strong> accept the recorded clause. MFN terms require a SAFE or note.</li><li><strong>Dividend events JSON</strong> and <strong>Economic basis JSON</strong> require a share certificate.</li><li>Values are validated as strictly as a form entry. A clause the app cannot calculate fails its row rather than importing without the term, and the row reports the reason.</li><li>MFN <em>elections</em> are never imported. Import the clause, then record an election from the security sheet so the elected terms always come from an instrument on file.</li></ul><p>The exported report is a review and transfer aid, not a restore format: it does not carry share classes, scenarios, or the source IDs an election refers to. Use a company JSON backup when you need a supported round trip. See <a href="/docs/recording-convertible-instruments/">Record SAFEs and convertible notes</a> and <a href="/docs/recording-preferred-dividends/">Record preferred dividends</a> for the terms themselves.</p>`),
      s('not-a-full-backup', 'Know what a CSV does not restore', `<p>The CSV field set is not a complete company-backup format. It does not import attachments, the audit trail, custom vesting tranches, acceleration terms, a full exercise/settlement history, or every option classification field. Review those terms in the app after importing; use a company JSON backup for a supported round trip of company data.</p><p>Files are limited to 10 MiB and 10,000 data rows per import, with additional company limits. An import adds securities rather than replacing the cap table. Correct errors and review duplicate warnings before saving.</p>`),
    ]),
  doc('calculation-methods-and-limits', 'Reference', 'Calculation methods and application limits',
    'Review Cap Table ownership, financing, vesting, reporting, and storage conventions before relying on a calculated result.',
    'Understand denominators, model assumptions, and supported limits.',
    ['reading-a-historical-cap-table', 'stock-compensation-report', 'troubleshooting-and-recovery', 'resolving-financing-refusals'], [
      s('ownership', 'Ownership and historical dates', `<p>Outstanding counts issued share certificates; fully diluted additionally counts relevant awards and warrants, optionally including available reserve from open plans. SAFEs and notes remain separate until conversion. Issued reverse-vesting stock stays outstanding.</p><p>An exercise without its certificate stays represented on the grant side until certified. Historical views use the dates preserved in current records and reverse relevant splits for earlier dates. They cannot reconstruct source history that was never recorded, and later corrections can change an earlier-date report.</p>`),
      s('models', 'Financing and exit assumptions', `<p>Round modeling uses the recorded valuation, investment, pre-money pool top-up, convertible terms, and supported anti-dilution methods. Note interest is simple interest using elapsed whole calendar days divided by 365, the same day count as dividend accrual. It stops at the recorded conversion date for later readings; resolving a maturity reminder does not stop accrual. Saved scenarios retain inputs and are recalculated against company records.</p><p>Exit modeling applies its note repayment, SAFE alternatives, preferences, and award participation conventions. It excludes escrow, fees, and tax. Neither model interprets bespoke contracts, calculates payroll, executes agreements, or transfers funds. Compare modeled results with the signed transaction’s calculation.</p>`),
      s('reporting', 'Vesting and expense conventions', `<p>Schedules support regular cadence or dated tranches. Custom rows express dated amounts, not an automated performance-condition test. Whole-share rounding can matter in schedules and splits.</p><p>The expense report uses Black-Scholes without dividends for options and recorded FMV for RSUs. Its current company assumptions apply when reports are rebuilt. Missing option FMV can fall back to strike; a missing usable expiration can fall back to ten years. An RSU without FMV is unvalued. These fallbacks are identified in report notes and need review.</p>`),
      s('limits', 'Current input and record limits', table('Application limits', ['Item', 'Limit'], [
        ['CSV file / data rows per import', '10 MiB / 10,000'], ['Company JSON import', '20 MiB'], ['Single attachment', '25 MiB'],
        ['Stakeholders / securities per company', '10,000 / 25,000'], ['Equity plans / valuations / stock splits per company', '40 of each'],
        ['Custom vesting schedule', '600 tranches'], ['Hiring plan', '100 roles; up to 500 hires per role'],
        ['Saved scenarios per company', '200 round scenarios and 200 exit scenarios'],
        ['Attachments per record', '20 files on one security or valuation'],
        ['Restore points', 'Up to five; size constraints can reduce retention'],
      ]) + `<p>Limits describe supported inputs, not a promise that every device will process the largest dataset equally quickly. A refused change should identify the relevant limit. Do not delete valid ownership history simply to fit a limit; export and review the appropriate next step.</p>`),
    ]),
  doc('dashboard-and-search', 'Start here', 'Use the dashboard, calendar, and search',
    'Understand the Cap Table Home dashboard, ownership charts, upcoming events, activity feed, global search, and navigation shortcuts.',
    'Find records and interpret the overview without losing context.',
    ['navigation-and-shortcuts', 'resolving-attention-items', 'reviewing-securities'], [
      s('metrics', 'Read the Home overview', `<p>Home summarizes the selected company’s outstanding and fully diluted shares, capital raised, implied valuation, and recorded FMV where available. Open the Cap table view when you need to inspect the ownership denominator and date explicitly.</p><p>Implied valuation and recorded FMV describe different measures. A valuation inferred from financing records is not an independent appraisal. The ownership chart can group the company by holder or share class; use the detailed rows to reconcile the underlying securities.</p><p>Capital raised totals original share-issuance consideration and SAFE/note principal, avoiding duplicate capital from linked conversions and transfers. It is not a current cash balance: note interest is not new invested principal and repurchases do not subtract from historical capital raised. Implied valuation uses the latest applicable priced issuance multiplied by the current fully diluted count, preferring a priced preferred issuance when available.</p><p>Home and stakeholder statements apply today’s date. The Cap table view applies its selected date. Future-dated records remain available in Securities and appear in ownership once effective. See <a href="/guides/reconciling-a-cap-table/">Reconcile a cap table</a> before changing records to make the two views match.</p><p>While setup is incomplete, Home also shows a <strong>Getting started</strong> checklist covering the company profile, a share class, founder shares, an adopted equity plan, and a first option grant or SAFE. Each step opens the view that records it, and the card disappears once every step is done. It is not shown while the sample company is loaded.</p>`),
      s('calendar', 'Review upcoming events and attention items', `<p>The calendar identifies recorded events such as cliffs, full vesting, expiration, note maturity, and relevant filing reminders. Check the underlying security and agreement before acting on a reminder.</p><p>Upcoming events and Needs attention serve different purposes: one shows dates to prepare for, while the other identifies recorded conditions requiring review. Neither replaces tracking obligations that are not represented in the app.</p>`),
      s('search', 'Find records with global search', `<p>Use <strong>Cmd+K</strong> on macOS or <strong>Ctrl+K</strong> on other platforms to open global search. The slash shortcut is also available outside text entry. Search holders, securities, classes, saved scenarios, and pages. Check the company context when opening a result.</p><p>Use the sidebar on desktop and the tabs and More menu on smaller screens to reach the other views. The documentation library has its own topic search, separate from the app’s company-record search.</p>`),
      s('activity', 'Distinguish recent activity from permanent History', `<p>The dashboard activity feed is a short recent summary. Use <strong>History</strong> for the permanent transaction trail, record filters, before-and-after values, and exports. A record’s effective date can differ from the time someone entered it.</p><p>If the app starts tracking a company without its earlier transaction trail, History identifies the incomplete baseline. Importing current balances does not manufacture the missing original events.</p>`),
    ]),
  doc('closing-a-funding-round', 'Ownership changes', 'Close a funding round in Cap Table',
    'Review investor allocations, preferred classes, convertible certificates, and equity-plan top-ups before applying a modeled financing.',
    'Turn reviewed round assumptions into linked company records.',
    ['modeling-a-funding-round', 'recording-convertible-instruments', 'financing-diligence-checklist', 'resolving-financing-refusals'], [
      s('prepare', 'Reconcile the model before closing', `<p>Use <strong>Round modeling</strong> to finalize the proposed valuation, new investment, and pool target. Check holder records, convertible terms, class rights, and current plan capacity against the signed financing records.</p><p>A saved scenario is a set of assumptions. Closing applies records to the company. Export a backup and resolve unexplained model differences before starting the close workflow.</p>`),
      s('allocate', 'Select the class, investors, and plan', `<p>Choose or create the preferred share class for the round. Allocate the new investment to the actual investors, using existing stakeholders where appropriate. Confirm the total allocation matches the proposed investment. A pro-rata check elected in the model arrives as a locked row for its holder and amount; change the election in Round modeling, not here. A new class can carry dated participation-cap and dividend terms from the start.</p><p>Select the destination equity plan for a pool top-up and review its terms. A company-wide target does not identify which plan should receive the reserve increase. The closing date defaults to the model date; choosing another day prices the round again on that day, and a date on which a right or election no longer applies is refused with the reason.</p>`),
      s('review', 'Review all proposed records together', `<p>Read the preview of new-investor certificates, conversion certificates, converted source instruments, and the reserve change. Review any anti-dilution adjustment in the model. Check names, quantities, prices, and effective dates rather than only the post-round percentages.</p><p>Integer share counts and rounding can differ from a financing spreadsheet’s intermediate precision; the review states what the checks add up to against what the whole shares are worth when they differ. Reconcile final quantities and monetary allocations before confirming. A restore point is taken before applying the close.</p><p>The close is held to its model. If the cap table has changed since the scenario was saved, the model refuses to close until the scenario is saved again; if a confirmed check, conversion, adjustment or top-up differs from what the model says for the closing date, the close is refused and nothing is written. Each certificate records the financing it belongs to, the assumptions it was priced under, the pro-rata right it satisfies or the MFN election applied to its source, and the same financing cannot be closed twice.</p>`),
      s('verify', 'Verify the result and retain the evidence', `<p>After the save completes, inspect the post-round cap table, investor statements, linked converted instruments, plan balance, and History. Export the final report with its basis and date.</p><p>The workflow records the financing; it does not sign agreements, obtain approvals, or transfer investment funds. If a save is interrupted, follow recovery prompts and inspect the result before trying to close again. See <a href="/docs/troubleshooting-and-recovery/">Troubleshooting and recovery</a>.</p>`),
    ]),
];
